  // Preview what would be removed without deleting (default: true)
  dry_run?: boolean;
  // When true, rebuild the FTS5 indexes and VACUUM to reclaim tombstone bloat that vacuum alone cannot (ADR-029). Runs standalone when no eviction is requested (ignores dry_run), otherwise after a non-dry-run eviction. Supersedes vacuum (default: false)
  optimize?: boolean;
  // When true, remove ALL knowledge base entries (sources, chunks, vocabulary) and reset session stats — a full project-scope reset. Cannot be combined with source, purge_ephemeral, or purge_session (default: false)
  purge_all?: boolean;
  // When true, only evict ephemeral sources past the TTL window; durable and session sources are untouched (default: false)
  purge_ephemeral?: boolean;
  // When true, only evict session sources past the TTL window; durable and ephemeral sources are untouched (default: false)
  purge_session?: boolean;
  // Evict a specific source by exact label, regardless of retention score or TTL
  source?: string;
